+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const limit = parseLimit(message.limit);
+  if (limit === null) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+
+  const cursor = parseCursor(message.before);
+  if (cursor === null) {
+    return {valid: false, error: 'list_sessions before must have a 1-128 char sessionId and valid updatedAt'};
+  }
+
+  const validated: ListSessionsMessage = {type: 'list_sessions'};
+  if (limit !== undefined) validated.limit = limit;
+  if (cursor !== undefined) validated.before = cursor;
+
+  return {valid: true, data: validated};
+}
+
+function parseLimit(limit: unknown): number | undefined | null {
+  if (limit === undefined) return undefined;
+  if (typeof limit !== 'number') return null;
+  return Number.isInteger(limit) && limit >= 0 ? limit : null;
+}
+
+function parseCursor(rawCursor: unknown): SessionCursor | undefined | null {
+  if (rawCursor === undefined) return undefined;
+  if (typeof rawCursor !== 'object' || rawCursor === null) return null;
+  if (Array.isArray(rawCursor)) return null;
+
+  const {sessionId, updatedAt} = rawCursor as Record<string, unknown>;
+  if (!isValidSessionId(sessionId) || !isValidUpdatedAt(updatedAt)) return null;
+
+  return {updatedAt, sessionId};
+}
+
+function isValidSessionId(sessionId: unknown): sessionId is string {
+  if (typeof sessionId !== 'string') return false;
+  return sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
+}
+
+function isValidUpdatedAt(updatedAt: unknown): updatedAt is string | number {
+  if (typeof updatedAt === 'string') {
+    return updatedAt.trim().length > 0 && Number.isFinite(Date.parse(updatedAt));
+  }
+  if (typeof updatedAt === 'number') {
+    return Number.isFinite(updatedAt) && Number.isFinite(new Date(updatedAt).getTime());
+  }
+  return false;
+}
